export interface DashSegmentBase {
    initialization: string;
    index_range: string;
    timescale?: number;
    earliest_presentation_time?: string;
}

/** One segment of a SegmentTimeline, in the template's timescale. */
export interface DashTimelineSegment {
    time: number;
    duration: number;
}

/**
 * How a Representation addresses its segments: byte ranges of one fMP4 file indexed by its sidx, or one URL per
 * segment generated by the server (just-in-time packaging), whose timeline already is the presentation timeline.
 */
export type DashSegments =
    | { kind: "base"; url: string; segment_base: DashSegmentBase }
    | { kind: "template"; timescale: number; initialization: string; media: string; timeline: DashTimelineSegment[] };

export interface DashVideoRepresentation {
    id: string;
    codec: string;
    bandwidth: number;
    width: number;
    height: number;
    frame_rate?: number | null;
    segments: DashSegments;
}

export interface DashAudioRepresentation {
    id: string;
    codec: string;
    bandwidth: number;
    language: string | null;
    label: string;
    role: string;
    channels: number;
    sample_rate?: number | null;
    audio_group_id?: string | null;
    segments: DashSegments;
}

export interface DashTextRepresentation {
    id: string;
    url: string;
    language: string | null;
    label: string;
    is_default: boolean;
}

export interface DashManifestInput {
    duration: number;
    video: DashVideoRepresentation[];
    audio: DashAudioRepresentation[];
    text?: DashTextRepresentation[];
}

export const escapeXml = (value: string | number) =>
    String(value).replace(/[<>&'"]/g, (character) => {
        if (character === "<") return "&lt;";
        if (character === ">") return "&gt;";
        if (character === "&") return "&amp;";
        if (character === "'") return "&apos;";
        return "&quot;";
    });

/** An exact time in seconds, `value / timescale`. */
interface Rational {
    value: bigint;
    timescale: bigint;
}

/** DASH defaults a missing SegmentBase@timescale to 1. */
const segmentTimescale = (segmentBase: DashSegmentBase) => BigInt(segmentBase.timescale ?? 1);

const earliestPresentationTime = (segmentBase: DashSegmentBase): Rational => ({
    value: BigInt(segmentBase.earliest_presentation_time ?? "0"),
    timescale: segmentTimescale(segmentBase),
});

/**
 * The Period-wide offset: the smallest EPT across every Representation. Zeroing each file on its
 * own would erase the offset between streams (B-frame delay, AAC priming) and desync audio and video.
 * A packaged Representation starts at presentation time 0, so it counts as an EPT of 0.
 */
const periodOffset = (segments: DashSegments[]): Rational =>
    segments
        .map((item) => (item.kind === "base" ? earliestPresentationTime(item.segment_base) : { value: 0n, timescale: 1n }))
        .reduce<Rational | null>(
        // a/b < c/d  <=>  a*d < c*b, all positive
        (min, time) => (min === null || time.value * min.timescale < min.value * time.timescale ? time : min),
        null,
    ) ?? { value: 0n, timescale: 1n };

/** The Period offset expressed in this Representation's timescale, rounded down so no media is cut off. */
const presentationTimeOffset = (offset: Rational, segmentBase: DashSegmentBase) =>
    (offset.value * segmentTimescale(segmentBase)) / offset.timescale;

const segmentBaseXml = (segmentBase: DashSegmentBase, offset: Rational, indentation: string) => {
    const attributes = [`indexRange="${escapeXml(segmentBase.index_range)}"`];
    if (segmentBase.timescale != null) attributes.push(`timescale="${escapeXml(segmentBase.timescale)}"`);
    const pto = presentationTimeOffset(offset, segmentBase);
    if (pto > 0n) attributes.push(`presentationTimeOffset="${pto}"`);

    return `${indentation}<SegmentBase ${attributes.join(" ")}>
${indentation}  <Initialization range="${escapeXml(segmentBase.initialization)}" />
${indentation}</SegmentBase>`;
};

/** Runs of equal durations collapse into one `S` with a repeat count. */
const timelineXml = (timeline: DashTimelineSegment[]) => {
    const entries: string[] = [];
    for (let i = 0; i < timeline.length; ) {
        let repeat = 0;
        while (i + repeat + 1 < timeline.length && timeline[i + repeat + 1]!.duration === timeline[i]!.duration) repeat++;
        entries.push(`<S t="${timeline[i]!.time}" d="${timeline[i]!.duration}"${repeat ? ` r="${repeat}"` : ""} />`);
        i += repeat + 1;
    }
    return entries.join("");
};

/** The BaseURL and segment addressing inside a Representation. */
const segmentsXml = (segments: DashSegments, offset: Rational, indentation: string) => {
    if (segments.kind === "base") {
        return `${indentation}<BaseURL>${escapeXml(segments.url)}</BaseURL>
${segmentBaseXml(segments.segment_base, offset, indentation)}`;
    }
    // The Period offset is 0 whenever a packaged Representation is present.
    return `${indentation}<SegmentTemplate timescale="${segments.timescale}" initialization="${escapeXml(segments.initialization)}" media="${escapeXml(segments.media)}" startNumber="0">
${indentation}  <SegmentTimeline>${timelineXml(segments.timeline)}</SegmentTimeline>
${indentation}</SegmentTemplate>`;
};

const videoRepresentationXml = (representation: DashVideoRepresentation, offset: Rational) => {
    const frameRate = representation.frame_rate ? ` frameRate="${escapeXml(representation.frame_rate)}"` : "";
    return `      <Representation id="${escapeXml(representation.id)}" codecs="${escapeXml(representation.codec)}" bandwidth="${escapeXml(representation.bandwidth)}" width="${escapeXml(representation.width)}" height="${escapeXml(representation.height)}"${frameRate}>
${segmentsXml(representation.segments, offset, "        ")}
      </Representation>`;
};

const audioGroupKey = (representation: DashAudioRepresentation) =>
    representation.audio_group_id ||
    [representation.language || "und", representation.role, representation.label, representation.channels].join("\u0000");

const groupAudioRepresentations = (representations: DashAudioRepresentation[]) => {
    const groups = new Map<string, DashAudioRepresentation[]>();
    for (const representation of representations) {
        const key = audioGroupKey(representation);
        const group = groups.get(key) ?? [];
        group.push(representation);
        groups.set(key, group);
    }
    return [...groups.values()];
};

const audioAdaptationSetXml = (representations: DashAudioRepresentation[], index: number, offset: Rational) => {
    const first = representations[0]!;
    const language = first.language ? ` lang="${escapeXml(first.language)}"` : "";
    const representationXml = representations
        .map((representation) => {
            const sampleRate = representation.sample_rate ? ` audioSamplingRate="${escapeXml(representation.sample_rate)}"` : "";
            return `      <Representation id="${escapeXml(representation.id)}" codecs="${escapeXml(representation.codec)}" bandwidth="${escapeXml(representation.bandwidth)}"${sampleRate}>
        <AudioChannelConfiguration schemeIdUri="urn:mpeg:dash:23003:3:audio_channel_configuration:2011" value="${escapeXml(representation.channels)}" />
${segmentsXml(representation.segments, offset, "        ")}
      </Representation>`;
        })
        .join("\n");

    return `    <AdaptationSet id="audio-${index + 1}" contentType="audio" mimeType="audio/mp4" segmentAlignment="true" startWithSAP="1"${language}>
      <Label>${escapeXml(first.label)}</Label>
      <Role schemeIdUri="urn:mpeg:dash:role:2011" value="${escapeXml(first.role)}" />
${representationXml}
    </AdaptationSet>`;
};

/** A WebVTT caption as a whole-file text AdaptationSet. */
const textAdaptationSetXml = (text: DashTextRepresentation, index: number) => {
    const language = text.language ? ` lang="${escapeXml(text.language)}"` : "";
    return `    <AdaptationSet id="text-${index + 1}" contentType="text" mimeType="text/vtt"${language}>
      <Label>${escapeXml(text.label)}</Label>
      <Role schemeIdUri="urn:mpeg:dash:role:2011" value="${text.is_default ? "main" : "subtitle"}" />
      <Representation id="${escapeXml(text.id)}" bandwidth="256">
        <BaseURL>${escapeXml(text.url)}</BaseURL>
      </Representation>
    </AdaptationSet>`;
};

export function buildDashManifest(input: DashManifestInput) {
    const duration = Number.isFinite(input.duration) && input.duration > 0 ? input.duration : 0;
    const offset = periodOffset([...input.video, ...input.audio].map((representation) => representation.segments));
    const video = input.video.map((representation) => videoRepresentationXml(representation, offset)).join("\n");
    const audio = groupAudioRepresentations(input.audio)
        .map((group, index) => audioAdaptationSetXml(group, index, offset))
        .join("\n");
    const text = (input.text ?? []).map(textAdaptationSetXml).join("\n");
    const audioSection = (audio ? `\n${audio}` : "") + (text ? `\n${text}` : "");

    return `<?xml version="1.0" encoding="utf-8"?>
<MPD xmlns="urn:mpeg:dash:schema:mpd:2011" profiles="urn:mpeg:dash:profile:isoff-on-demand:2011,urn:mpeg:dash:profile:isoff-live:2011" type="static" mediaPresentationDuration="PT${escapeXml(duration)}S" minBufferTime="PT1.5S">
  <Period>
    <AdaptationSet id="video" contentType="video" mimeType="video/mp4" segmentAlignment="true" startWithSAP="1">
${video}
    </AdaptationSet>${audioSection}
  </Period>
</MPD>`;
}
